// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 v) public {
        // withdraw(v) transfers v from c to msg.sender; it must revert whenever v
        // exceeds the contract's balance. c's balance stays 0 here (no funding),
        // so any v > 0 must revert in the reference. bound keeps v admissible.
        v = bound(v, 1, type(uint256).max);
        vm.assume(address(c).balance < v);

        bool ok;
        try c.withdraw(v) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "withdraw exceeding balance must revert");
    }
}
